INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1ddc649c90d935be6dfe','Amedex 2023.pdf','1122','Mixed/Unclassified','A 27-year-old female, who is 37 weeks pregnant, presents to the Emergency Department with sudden onset of severe headache. She feels nauseous and dizzy. Her mother noted slurred speech and repetition of words after the headache started. She
is clinically stable and has not had any obstetric complication so far. She has no history of migraine. Which one of the following would be the most appropriate next step in management?','{"A":"Aspirin.","B":"CT scan of the brain.","C":"MRI of the brain.","D":"Lumbar puncture.","E":"Observation in the ward."}','B','The clinical picture is suggestive of subarachnoid hemorrhage (SAH), and non-contrast CT scan of the brain would be the next best step in management.
Pregnancy is a recognized risk factor for aneurysmal SAH. SAH is a very rare complication of pregnancy and may be confused with eclampsia, due to similar presentation with high blood pressure, seizures and altered levels of consciousness. Once
the condition is suspected, the diagnosis is confirmed with CT scan (preferred), MR, or cerebral angiography. Although CT scanning exposes the fetus to radiation, the benefits significantly outweighs the risks. Appropriate covering of the uterus may
reduce the risks to the fetus.
(Option A) Aspirin should be avoided unless full assessment excludes the possibility of intracranial hemorrhage.
(Option C) CT scan is more sensitive than MRI in detection of blood and is the first-line investigation where intracranial hemorrhage is suspected.
(Option D) If CT scan of the brain is inconclusive, lumbar puncture comes next. It should be performed within 12 hours after the onset of the symptoms.
(Option E) Subarachnoid hemorrhage is a real emergency demanding immediate workup; therefore, just observing the patient in the ward would be inappropriate.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"429","duplicate_group_id":"exact-d731c82c6379","duplicate_sources":[{"record_id":"1ddc649c90d935be6dfe","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1122,"source_qid":"429"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"1ddc649c90d935be6dfe","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1122,"source_qid":"429","domain_hint":"Mixed/Unclassified","stem":"A 27-year-old female, who is 37 weeks pregnant, presents to the Emergency Department with sudden onset of severe headache. She feels nauseous and dizzy. Her mother noted slurred speech and repetition of words after the headache started. She\nis clinically stable and has not had any obstetric complication so far. She has no history of migraine. Which one of the following would be the most appropriate next step in management?","options":{"A":"Aspirin.","B":"CT scan of the brain.","C":"MRI of the brain.","D":"Lumbar puncture.","E":"Observation in the ward."},"source_answer":"B","source_explanation":"The clinical picture is suggestive of subarachnoid hemorrhage (SAH), and non-contrast CT scan of the brain would be the next best step in management.\nPregnancy is a recognized risk factor for aneurysmal SAH. SAH is a very rare complication of pregnancy and may be confused with eclampsia, due to similar presentation with high blood pressure, seizures and altered levels of consciousness. Once\nthe condition is suspected, the diagnosis is confirmed with CT scan (preferred), MR, or cerebral angiography. Although CT scanning exposes the fetus to radiation, the benefits significantly outweighs the risks. Appropriate covering of the uterus may\nreduce the risks to the fetus.\n(Option A) Aspirin should be avoided unless full assessment excludes the possibility of intracranial hemorrhage.\n(Option C) CT scan is more sensitive than MRI in detection of blood and is the first-line investigation where intracranial hemorrhage is suspected.\n(Option D) If CT scan of the brain is inconclusive, lumbar puncture comes next. It should be performed within 12 hours after the onset of the symptoms.\n(Option E) Subarachnoid hemorrhage is a real emergency demanding immediate workup; therefore, just observing the patient in the ward would be inappropriate.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d731c82c63794b7149c29379d3d1258f691f6ec4","duplicate_group_id":"exact-d731c82c6379","duplicate_sources":[{"record_id":"1ddc649c90d935be6dfe","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1122,"source_qid":"429"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
