INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5ebb479e4f0dfec21240','Amedex 2023.pdf','1124','Mixed/Unclassified','A 32-year old woman comes to your clinic for advice. She is 12-week pregnant, and has already been on folic acid for the past 24 weeks. Which one of the following should be started for her?','{"A":"Iodine for a few weeks.","B":"Vitamin B12 injections.","C":"Vitamin A supplements.","D":"Vitamin C.","E":"Iodine throughout the pregnancy."}','E','Clinical guidelines for antenatal care by National Health and Medical Research Council of Australia recommend folic acid 0.5 mg daily 12 weeks before conception and during first trimester. The dose of folic acid is increased to 5mg daily in the
following situations:
History of neural tube defects in previous pregnancies
The pregnant woman is diabetic
The pregnant woman is on anticonvulsant medications
The mother is also recommended to take 150 microgram of iodine on a daily basis throughout the pregnancy for prevention of iodine deficiency in the fetus.
She has taken folic acid for the first trimester; therefore it can safely be stopped.
While there is evidence to support routine supplementation with folic acid and iodine in pregnancy, other vitamin and mineral supplements are not of benefit unless there is an identified deficiency. Vitamin A, B and C supplements are not routinely
used in pregnancy.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"431","duplicate_group_id":"exact-db56f4b7ab8c","duplicate_sources":[{"record_id":"5ebb479e4f0dfec21240","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1124,"source_qid":"431"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"5ebb479e4f0dfec21240","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1124,"source_qid":"431","domain_hint":"Mixed/Unclassified","stem":"A 32-year old woman comes to your clinic for advice. She is 12-week pregnant, and has already been on folic acid for the past 24 weeks. Which one of the following should be started for her?","options":{"A":"Iodine for a few weeks.","B":"Vitamin B12 injections.","C":"Vitamin A supplements.","D":"Vitamin C.","E":"Iodine throughout the pregnancy."},"source_answer":"E","source_explanation":"Clinical guidelines for antenatal care by National Health and Medical Research Council of Australia recommend folic acid 0.5 mg daily 12 weeks before conception and during first trimester. The dose of folic acid is increased to 5mg daily in the\nfollowing situations:\nHistory of neural tube defects in previous pregnancies\nThe pregnant woman is diabetic\nThe pregnant woman is on anticonvulsant medications\nThe mother is also recommended to take 150 microgram of iodine on a daily basis throughout the pregnancy for prevention of iodine deficiency in the fetus.\nShe has taken folic acid for the first trimester; therefore it can safely be stopped.\nWhile there is evidence to support routine supplementation with folic acid and iodine in pregnancy, other vitamin and mineral supplements are not of benefit unless there is an identified deficiency. Vitamin A, B and C supplements are not routinely\nused in pregnancy.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["dose","guideline","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"db56f4b7ab8c1d5e84ecb1d5d87bf89ad1774946","duplicate_group_id":"exact-db56f4b7ab8c","duplicate_sources":[{"record_id":"5ebb479e4f0dfec21240","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1124,"source_qid":"431"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
