INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('5ebb479e4f0dfec21240','src-v294-687f312c','431','1124','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 32-year old woman comes to your clinic for advice. She is 12-week pregnant, and has already been on folic acid for the past 24 weeks. Which one of the following should be started for her?',NULL,'E','Clinical guidelines for antenatal care by National Health and Medical Research Council of Australia recommend folic acid 0.5 mg daily 12 weeks before conception and during first trimester. The dose of folic acid is increased to 5mg daily in the
following situations:
History of neural tube defects in previous pregnancies
The pregnant woman is diabetic
The pregnant woman is on anticonvulsant medications
The mother is also recommended to take 150 microgram of iodine on a daily basis throughout the pregnancy for prevention of iodine deficiency in the fetus.
She has taken folic acid for the first trimester; therefore it can safely be stopped.
While there is evidence to support routine supplementation with folic acid and iodine in pregnancy, other vitamin and mineral supplements are not of benefit unless there is an identified deficiency. Vitamin A, B and C supplements are not routinely
used in pregnancy.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"431","duplicate_group_id":"exact-db56f4b7ab8c","duplicate_sources":[{"record_id":"5ebb479e4f0dfec21240","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1124,"source_qid":"431"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
