INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5f39c46a5fb2c924a170','Amedex 2023.pdf','1126','Mixed/Unclassified','A 34-year-old pregnant woman presents at 32 weeks pregnancy for an antenatal visit. On pelvic examination, breech presentation is suspected. Ultrasound shows that fetal hips are flexed, and the knees extended. Which one of the following is this
presentation called?','{"A":"Complete breech.","B":"Frank breech.","C":"Footling breech.","D":"Kneeling breech.","E":"Transverse lie."}','B','Types of breech presentation include:
Frank breech: The fetal hips are flexed, and the knees extended.
Complete breech: The fetus seems to be sitting with hips and knees flexed.
Footling breech: One or both legs are completely extended and present before the buttocks.
Kneeling breech: The baby is in a kneeling position, with one or both legs extended at the hips and flexed at the knees.
Fetal position is transverse if the fetal long axis is oblique or perpendicular rather than parallel to the maternal long axis.
With the hips flexed and knees extended, this fetus has Frank breech presentation. This type is the most common breech presentation.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"433","duplicate_group_id":"exact-88f18a5e60c4","duplicate_sources":[{"record_id":"5f39c46a5fb2c924a170","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1126,"source_qid":"433"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"5f39c46a5fb2c924a170","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1126,"source_qid":"433","domain_hint":"Mixed/Unclassified","stem":"A 34-year-old pregnant woman presents at 32 weeks pregnancy for an antenatal visit. On pelvic examination, breech presentation is suspected. Ultrasound shows that fetal hips are flexed, and the knees extended. Which one of the following is this\npresentation called?","options":{"A":"Complete breech.","B":"Frank breech.","C":"Footling breech.","D":"Kneeling breech.","E":"Transverse lie."},"source_answer":"B","source_explanation":"Types of breech presentation include:\nFrank breech: The fetal hips are flexed, and the knees extended.\nComplete breech: The fetus seems to be sitting with hips and knees flexed.\nFootling breech: One or both legs are completely extended and present before the buttocks.\nKneeling breech: The baby is in a kneeling position, with one or both legs extended at the hips and flexed at the knees.\nFetal position is transverse if the fetal long axis is oblique or perpendicular rather than parallel to the maternal long axis.\nWith the hips flexed and knees extended, this fetus has Frank breech presentation. This type is the most common breech presentation.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"88f18a5e60c413402291a4f65d8dd1278053a927","duplicate_group_id":"exact-88f18a5e60c4","duplicate_sources":[{"record_id":"5f39c46a5fb2c924a170","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1126,"source_qid":"433"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
