INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('5f39c46a5fb2c924a170','src-v294-687f312c','433','1126','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 34-year-old pregnant woman presents at 32 weeks pregnancy for an antenatal visit. On pelvic examination, breech presentation is suspected. Ultrasound shows that fetal hips are flexed, and the knees extended. Which one of the following is this
presentation called?',NULL,'B','Types of breech presentation include:
Frank breech: The fetal hips are flexed, and the knees extended.
Complete breech: The fetus seems to be sitting with hips and knees flexed.
Footling breech: One or both legs are completely extended and present before the buttocks.
Kneeling breech: The baby is in a kneeling position, with one or both legs extended at the hips and flexed at the knees.
Fetal position is transverse if the fetal long axis is oblique or perpendicular rather than parallel to the maternal long axis.
With the hips flexed and knees extended, this fetus has Frank breech presentation. This type is the most common breech presentation.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"433","duplicate_group_id":"exact-88f18a5e60c4","duplicate_sources":[{"record_id":"5f39c46a5fb2c924a170","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1126,"source_qid":"433"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
