INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4b68b8211db4909294f5','Amedex 2023.pdf','1138','Mixed/Unclassified','Which one of the following cannot be associated with HLA- B27?','{"A":"Acute anterior uveitis.","B":"Ankylosing spondylitis.","C":"Reactive arthritis.","D":"Behçet disease.","E":"Psoriatic arthritis."}','D','HLA-B27 is found in almost 90% of patients with seronegative spondyloarthropathies. Seronegative spondyloarthropathies include:
Ankylosing spondylitis (AS)
Reactive arthritis
Psoriatic arthritis
Inflammatory bowel disease
Anterior uveitis is another possible finding in seronegative spondyloarthropathies; hence, from another standpoint, it could be said that those with anterior uveitis may suffer from a
seronegative spondyloarthropathy and consequently be HLA-B27 positive.
Behçet disease is a diffuse vasculitis of unknown origin. The disease is characterized by a triple-symptom complex of:
1. Recurrent oral aphthous ulcers
2. Recurrent genital ulcers
3. Uveitis
Behçet disease has no association with HLA-B27.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"557","duplicate_group_id":"exact-90686c76329f","duplicate_sources":[{"record_id":"4b68b8211db4909294f5","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1138,"source_qid":"557"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"4b68b8211db4909294f5","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1138,"source_qid":"557","domain_hint":"Mixed/Unclassified","stem":"Which one of the following cannot be associated with HLA- B27?","options":{"A":"Acute anterior uveitis.","B":"Ankylosing spondylitis.","C":"Reactive arthritis.","D":"Behçet disease.","E":"Psoriatic arthritis."},"source_answer":"D","source_explanation":"HLA-B27 is found in almost 90% of patients with seronegative spondyloarthropathies. Seronegative spondyloarthropathies include:\nAnkylosing spondylitis (AS)\nReactive arthritis\nPsoriatic arthritis\nInflammatory bowel disease\nAnterior uveitis is another possible finding in seronegative spondyloarthropathies; hence, from another standpoint, it could be said that those with anterior uveitis may suffer from a\nseronegative spondyloarthropathy and consequently be HLA-B27 positive.\nBehçet disease is a diffuse vasculitis of unknown origin. The disease is characterized by a triple-symptom complex of:\n1. Recurrent oral aphthous ulcers\n2. Recurrent genital ulcers\n3. Uveitis\nBehçet disease has no association with HLA-B27.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence"