INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('85311ba66a4e7d505c86','Amedex 2023.pdf','1160','Mixed/Unclassified','Which one of the following are the most appropriate medications to give prior to reduction of an anterior dislocation of the shoulder?','{"A":"IV diazepam and morphine.","B":"IV midazolam.","C":"Intranasal fentanyl and IV midazolam.","D":"IV midazolam and morphine.","E":"IM diazepam and nasal fentanyl."}','C','Reduction of anterior shoulder dislocation is performed in the emergency department after adequate muscle relaxation and sedation is provided. Intravenous midazolam plus
intranasal fentanyl (an opiate) is the most commonly used drug combination.
Ketamine, etomidate and propofol are other appropriate alternatives.
Use of parenteral morphine is not justified while intranasal fentanyl can provide the same pain relief. Fentanyl is easier to administer. Diazepam is a long-acting benzodiazepine.
While a short duration of muscle relaxation is required for joint reduction, use of midazolam in preference of diazepam is more appropriate. Furthermore, IM diazepam has an
delayed and unpredictable effect.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1160","duplicate_group_id":"exact-9ed3c3a7bc55","duplicate_sources":[{"record_id":"85311ba66a4e7d505c86","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1160,"source_qid":"1160"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"85311ba66a4e7d505c86","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1160,"source_qid":"1160","domain_hint":"Mixed/Unclassified","stem":"Which one of the following are the most appropriate medications to give prior to reduction of an anterior dislocation of the shoulder?","options":{"A":"IV diazepam and morphine.","B":"IV midazolam.","C":"Intranasal fentanyl and IV midazolam.","D":"IV midazolam and morphine.","E":"IM diazepam and nasal fentanyl."},"source_answer":"C","source_explanation":"Reduction of anterior shoulder dislocation is performed in the emergency department after adequate muscle relaxation and sedation is provided. Intravenous midazolam plus\nintranasal fentanyl (an opiate) is the most commonly used drug combination.\nKetamine, etomidate and propofol are other appropriate alternatives.\nUse of parenteral morphine is not justified while intranasal fentanyl can provide the same pain relief. Fentanyl is easier to administer. Diazepam is a long-acting benzodiazepine.\nWhile a short duration of muscle relaxation is required for joint reduction, use of midazolam in preference of diazepam is more appropriate. Furthermore, IM diazepam has an\ndelayed and unpredictable effect.","source_answer_status":"present","current_a