INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('40a6d84fffb3177fa80a','Amedex 2023.pdf','1163','Mixed/Unclassified','A 76-year-old lady presents to the emergency department after she sustained a fall on her outstretched hand. The X-ray obtained is shown in the following photograph. Which one of
the following should be the position of the the wrist in cast?','{"A":"Full flexion of the wrist with radial deviation.","B":"Partial flexion of the wrist with radial deviation.","C":"Full flexion of the wrist with ulnar deviation.","D":"Partial extension of the wrist with radial deviation.","E":"Partial flexion of the wrist with ulnar deviation."}','E','The X-ray shows fracture of the distal radius, also known as Colles fracture. Falling on an outstretched (dorsiflexed) hand is the most common mechanism of this fracture. Colles
fracture is very common in elderly women, and can occur with minimal trauma if there is osteoporosis.
There can be posterior dislocation of the head of the radius, giving rise to the ''fork deformity''. Lateral displacement may also occur. Casts are often used for treatment of Colles
fractures. Severely displaced fractures may be treated with external or even internal fixation.
For casting, the wrist should be in 10° flexion and 10° ulnar deviation, and the forearm must be in slight pronation. Often a below-elbow cast for 4-6 week is sufficient; however, the
cast may be extend to include above the elbow if there is significant displacement. Every significant displacement should be reduced under anesthesia before casting.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1163","duplicate_group_id":"exact-e42a0c2aad45","duplicate_sources":[{"record_id":"40a6d84fffb3177fa80a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1163,"source_qid":"1163"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"40a6d84fffb3177fa80a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1163,"source_qid":"1163","domain_hint":"Mixed/Unclassified","stem":"A 76-year-old lady presents to the emergency department after she sustained a fall on her outstretched hand. The X-ray obtained is shown in the following photograph. Which one of\nthe following should be the position of the the wrist in cast?","options":{"A":"Full flexion of the wrist with radial deviation.","B":"Partial flexion of the wrist with radial deviation.","C":"Full flexion of the wrist with ulnar deviation.","D":"Partial extension of the wrist with radial deviation.","E":"Partial flexion of the wrist with ulnar deviation."},"source_answer":"E","source_explanation":"The X-ray shows fracture of the distal radius, also known as Colles fracture. Falling on an outstretched (dorsiflexed) hand is the most common mechanism of this fracture. Colles\nfracture is very common in elderly women, and can occur with minimal trauma if there is osteoporosis.\nThere can be posterior dislocation of the head of the radius, giving rise to the ''fork deformity''. Lateral dis