INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fa3a64be42f841c7a442','Amedex 2023.pdf','1203','Mixed/Unclassified','Which one of the following is NOT an expected physical finding in infectious tenosynovitis of finger?','{"A":"Pain on passive flexion of the affected finger.","B":"Pain on passive extension of the affected finger.","C":"Finger in fixed flexion.","D":"Fusiform swelling of the whole finger.","E":"Tenderness along the flexor tendon sheath."}','A','Flexor sheath infections, also known as infective tenosynovitis, are relatively common hand infections.
Digital flexor sheaths are a closed continuous synovial system that contain the flexor digitorum profundus and flexor digitorum superficialis. Flexor sheath infections are caused by
direct inoculation due to trauma, spread of infection from adjacent tissues, or via hematogenous spread. Common injuries include animal bites, puncture wounds, IV drug use, and
wounds exposed to fresh/saltwater. Such injuries, if associated with severe tenderness, should raise a high suspicion of flexor tenosynovitis.
Infective flexor tenosynovitis of the middle finger 
Flexor sheath infections begin with buildup of exudative fluid within the tendon sheath, followed by the development of purulent fluid. Bacterial overgrowth within the synovial sheath
leads to increased fluid and pressure, leading to ischemia, and resulting in a septic necrosis of the tendon sheath and surrounding structures. If left untreated, complications may
include soft tissue necrosis, osteomyelitis, and necrotizing fasciitis.
Infective flexor tenosynovitis presents with the four cardinal signs referred to as Kanavel signs:
Flexed resting position of the affected finger
Fusiform swelling of the whole finger
Tenderness along the flexor tendon sheath
Pain (usually exquisite) with passive extension of the affected finger
Of the options, pain on passive flexion of the affected finger is not a feature.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-79fa7da7a148","duplicate_sources":[{"record_id":"fa3a64be42f841c7a442","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1203,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"fa3a64be42f841c7a442","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1203,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Which one of the following is NOT an expected physical finding in infectious tenosynovitis of finger?","options":{"A":"Pain on passive flexion of the affected finger.","B":"Pain on passive extension of the affected finger.","C":"Finger in fixed flexion.","D":"Fusiform swelling of the whole finger.","E":"Tenderness along the flexor tendon sheath."},"source_answer":"A","source_explanation":"Flexor sheath infections, also known as infective tenosynovitis, are relatively common hand infections.\nDigital flexor sheaths are a closed continuous synovial system that contain the flexor digitorum profundus and flexor digitorum superficialis. Flexor sheath infections are caused by\ndirect inoculation due to trauma, spread of infection from adjacent tissues, or via hematogenous spread. Common injuries include animal bites, puncture wounds, IV drug use, and\nwounds exposed to fresh/saltwater. Such injuries, if associated with severe tenderness, should raise a high suspicion of flexor tenosynovitis.\nInfective flexor tenosynovitis of the middle finger \nFlexor sheath infections begin with buildup of exudative fluid within the tendon sheath, followed by the development of purulent fluid. Bacterial overgrowth within the synovial sheath\nleads to increased fluid and pressure, leading to ischemia, and resulting in a septic necrosis of the tendon sheath and surrounding structures. If left untreated, complications may\ninclude soft tissue necrosis, osteomyelitis, and necrotizing fasciitis.\nInfective flexor tenosynovitis presents with the four cardinal signs referred to as Kanavel signs:\nFlexed resting position of the affected finger\nFusiform swelling of the whole finger\nTenderness along the flexor tendon sheath\nPain (usually exquisite) with passive extension of the affected finger\nOf the options, pain on passive flexion of the affected finger is not a feature.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["drug"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"79fa7da7a1486a6862615f46c579a82cd9c26cf1","duplicate_group_id":"exact-79fa7da7a148","duplicate_sources":[{"record_id":"fa3a64be42f841c7a442","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1203,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_ans