INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('788bf62d468d5bc211c1','Amedex 2023.pdf','1220','Mixed/Unclassified','Concerned parents of a 6-year-old girl has brought her to your GP clinic as they have noticed scattered growth of
pubic hair in their daughter recently. On examination, she has sparse pubic hair growth and Tanner I breast. Her
height and weight are on 75% and 50% percentiles respectively. Which one of the following is the most appropriate
next step in management?','{"A":"Ultrasounds scan of the pelvis.","B":"Assessment of the bone age.","C":"FSH and LH.","D":"Review in 3 months.","E":"17-hydroxyprogesterone and estradiol."}','D','The scenario represents development of pubic hair before the age of 8 years in girls (or 9 in boys) in the absence
other sexual characteristics which are thelarche (breast development) and menarche (periods), which is referred to
as premature isolated adrenarche. Adrenarche is the maturation of the adrenal zona reticularis in both boys and girls,
resulting in the development of pubic hair, axillary hair, and adult apocrine body odor. Premature isolated adrenarche
is considered a benign variant of normal development if the weight and height are normal for the age.
No investigations are required for premature isolated adrenarche as FSH and LH (option C), 17-hydroxyprogesterone
and estradiol (option E), and testosterone all normal. The only laboratory finding might be slight elevation of
dehydroepiandrosterone sulfate (DHEAS). It is recommended that children with premature isolated adrenarche are
followed every 3-6 months for surveillance of puberty development and linear progression and velocity of growth.
Bone age assessment (option B) is considered in constitutional growth delay (CGD) alongside exclusion of other
causes of delayed puberty/growth to confirm the diagnosis or where the child is small for age. This child has normal
weight and height for age.
Ultrasound of the pelvis (option A) is the study of choice for girls whose periods are overdue despite development of
other secondary sexual characteristics, normal body measures, and absence of features suggesting chromosomal
abnormalities such as Turner syndrome.
NOTE– puberty starts with thelarche. A Tanner II breast before the age of 13 years suggests estrogen exposure and
commencement of puberty in girls. This is equivalent to testicular enlargement in boys. A Tanner II or less after 13
years is abnormal and indicated absence of breast development.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1672","duplicate_group_id":"exact-b1ee7b61355b","duplicate_sources":[{"record_id":"788bf62d468d5bc211c1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1220,"source_qid":"1672"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"788bf62d468d5bc211c1","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1220,"source_qid":"1672","domain_hint":"Mixed/Unclassified","stem":"Concerned parents of a 6-year-old girl has brought her to your GP clinic as they have noticed scattered growth of\npubic hair in their daughter recently. On examination, she has sparse pubic hair growth and Tanner I breast. Her\nheight and weight are on 75% and 50% percentiles respectively. Which one of the following is the most appropriate\nnext step in management?","options":{"A":"Ultrasounds scan of the pelvis.","B":"Assessment of the bone age.","C":"FSH and LH.","D":"Review in 3 months.","E":"17-hydroxyprogesterone and estradiol."},"source_answer":"D","source_explanation":"The scenario represents development of pubic hair before the age of 8 years in girls (or 9 in boys) in the absence\nother sexual characteristics which are thelarche (breast development) and menarche (periods), which is referred to\nas premature isolated adrenarche. Adrenarche is the maturation of the adrenal zona reticularis in both boys and girls,\nresulting in the development of pubic hair, axillary hair, and adult apocrine body odor. Premature isolated adrenarche\nis considered a benign variant of normal development if the weight and height are normal for the age.\nNo investigations are required for premature isolated adrenarche as FSH and LH (option C), 17-hydroxyprogesterone\nand estradiol (option E), and testosterone all normal. The only laboratory finding might be slight elevation of\ndehydroepiandrosterone sulfate (DHEAS). It is recommended that children with premature isolated adrenarche are\nfollowed every 3-6 months for surveillance of puberty development and linear progression and velocity of growth.\nBone age assessment (option B) is considered in constitutional growth delay (CGD) alongside exclusion of other\ncauses of delayed puberty/growth to confirm the diagnosis or where the child is small for age. This child has normal\nweight and height for age.\nUltrasound of the pelvis (option A) is the study of choice for girls whose periods are overdue despite development of\nother secondary sexual characteristics, normal body measures, and absence of features suggesting chromosomal\nabnormalities such as Turner syndrome.\nNOTE– puberty starts with thelarche. A Tanner II breast before the age of 13 years suggests estrogen exposure and\ncommencement of puberty in girls. This is equivalent to testicular enlargement in boys. A Tanner II or less after 13\nyears is abnormal and indicated absence of breast development.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b1ee7b61355b40102ae1ec67cdc0ef269a968672","duplicate_group_id":"exact-b1ee7b61355b","duplicate_sources":[{"record_id":"788bf62d468d5bc211c1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+han