INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('abb3c1f84f0cfee65665','Amedex 2023.pdf','1223','Mixed/Unclassified','Emad is 6 years old and is being rushed to the Emergency Department by an ambulance after he experienced light-
headedness, shortness of breath, chest tightness, and anxiousness at home 15 minutes ago. When you visit him, he
is lying on a stretched and is receiving oxygen by non-re-breathable face mask. He is mumbling and does not seem
to be oriented to time and place however he seems to recognize his parents. Examination reveals a very rapid barely
perceptible pulse and blood pressure of 80/45 mmHg. Cardiac monitoring shows the following rhythm. Which one of
the following is the most appropriate immediate management in this situation?','{"A":"Defibrillation.","B":"Synchronized DC cardioversion.","C":"Intravenous amiodarone.","D":"Intravenous lignocaine.","E":"Intravenous adenosine."}','B','Emad’s ECG shows tachycardia of approximately 300 bpm with regular wide QRS complexes (wide-QRS complex
tachycardia [WCT]). In children, ventricular tachycardia (VT) is very rare, and most WTCs are in fact supraventricular
tachycardia with conduction aberrancy (SVT with aberrancy). However, due to seriousness of VT compared to SVT,
guidelines such Advanced Paediatric Life Support (APLS) as those by the Royal Children Hospital (RCH) recommend
that WCTs should be considered and treated as VT until prove otherwise.
As such, Emad’s ECG should be considered and treated as VT. Treatment of VT with a pulse is determined by the
presence or absence of shock/hemodynamic instability (hypotension, hypoperfusion, altered mental status)
For every patient presenting with hemodynamic instability caused by a cardiac tachyarrhythmia, DC cardioversion
should always be considered as the most appropriate treatment option (defibrillation for ventricular fibrillation and
pulseless VT; synchronized for the rest.)
Emad has an ECG with WCT in addition to hypotension and hypoperfusion evident by altered mental status
(disorientation to time and place) and cold pale sweaty extremities. Of the options, synchronized DC cardioversion is
the next step in treatment to consider for him.
Defibrillation (unsynchronized) (option A) is used as first line for treatment of ventricular fibrillation (VF) and
pulseless VT.
If Emad was not hemodynamically unstable, intravenous amiodarone (option C) would be considered first.
Amiodarone is the medication of choice for children presenting with symptomatic wide QRS tachycardia who are not
in shock.
Intravenous amiodarone (class III antiarrhythmic) is almost always the medication of choice for treatment of
symptomatic VT in stable infants and young children. The medication has a broad efficacy and is readily available.
However, major adverse reactions have always been concerning.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-84edf88511e8","duplicate_sources":[{"record_id":"abb3c1f84f0cfee65665","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1223,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"abb3c1f84f0cfee65665","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1223,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Emad is 6 years old and is being rushed to the Emergency Department by an ambulance after he experienced light-\nheadedness, shortness of breath, chest tightness, and anxiousness at home 15 minutes ago. When you visit him, he\nis lying on a stretched and is receiving oxygen by non-re-breathable face mask. He is mumbling and does not seem\nto be oriented to time and place however he seems to recognize his parents. Examination reveals a very rapid barely\nperceptible pulse and blood pressure of 80/45 mmHg. Cardiac monitoring shows the following rhythm. Which one of\nthe following is the most appropriate immediate management in this situation?","options":{"A":"Defibrillation.","B":"Synchronized DC cardioversion.","C":"Intravenous amiodarone.","D":"Intravenous lignocaine.","E":"Intravenous adenosine."},"source_answer":"B","source_explanation":"Emad’s ECG shows tachycardia of approximately 300 bpm with regular wide QRS complexes (wide-QRS complex\ntachycardia [WCT]). In children, ventricular tachycardia (VT) is very rare, and most WTCs are in fact supraventricular\ntachycardia with conduction aberrancy (SVT with aberrancy). However, due to seriousness of VT compared to SVT,\nguidelines such Advanced Paediatric Life Support (APLS) as those by the Royal Children Hospital (RCH) recommend\nthat WCTs should be considered and treated as VT until prove otherwise.\nAs such, Emad’s ECG should be considered and treated as VT. Treatment of VT with a pulse is determined by the\npresence or absence of shock/hemodynamic instability (hypotension, hypoperfusion, altered mental status)\nFor every patient presenting with hemodynamic instability caused by a cardiac tachyarrhythmia, DC cardioversion\nshould always be considered as the most appropriate treatment option (defibrillation for ventricular fibrillation and\npulseless VT; synchronized for the rest.)\nEmad has an ECG with WCT in addition to hypotension and hypoperfusion evident by altered mental status\n(disorientation to time and place) and cold pale sweaty extremities. Of the options, synchronized DC cardioversion is\nthe next step in treatment to consider for him.\nDefibrillation (unsynchronized) (option A) is used as first line for treatment of ventricular fibrillation (VF) and\npulseless VT.\nIf Emad was not hemodynamically unstable, intravenous amiodarone (option C) would be considered first.\nAmiodarone is the medication of choice for children presenting with symptomatic wide QRS tachycardia who are not\nin shock.\nIntravenous amiodarone (class III antiarrhythmic) is almost always the medication of choice for treatment of\nsymptomatic VT in stable infants and young children. The medication has a broad efficacy and is readily available.\nHowever, major adverse reactions have always been concerning.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","guideline","management","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"84edf88511e8c994745c6aa8de0dbc3ee5b75525","duplicate_group_id":"exact-84edf88511e8","duplicate_sources":[{"record_id":"abb3c1f84f0cfee65665","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1223,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
