INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ab22302b44d194447f2a','Amedex 2023.pdf','1277','Mixed/Unclassified','A 2-year-old boy is brought to your clinic due to a 3-day history of fever with occasional cough and coryza. On clinical
history, viral upper respiratory tract infection is suspected. On physical examination, the patient is noted to have
down-slanting of palpebral fissures, eyes that are apart more than usual and low-set ears. The height of the patient is
smaller than the standard. Which one of the following is not consistent with this condition?','{"A":"Pulmonary valve stenosis.","B":"Myopia and ectopic ocular lens.","C":"An autosomal disorder involving mutation in chromosome 11.","D":"Webbed neck.","E":"Abnormalities in cardiac conduction and rhythm."}','B','This clinical picture is suggestive of Noonan syndrome. This is an autosomal dominant disorder with mutation of
chromosome 11. It has been described as the male Turner''s syndrome, but affects both sexes.
Clinical features of the syndrome include the following:
Facial/eye features
Triangular face
Hypertelorism (increased distance between the eyes)
Down-slanting eyes
Ptosis
Strabismus – seen in 48%
Amblyopia – seen in 33%
Refractive errors – seen in 61%
Low-set ears with thickened helices
High nasal bridge
Short webbed neck
Chest/back features
Pectus carinatum/excavatum
Scoliosis
Cardiac features
Stenotic/dysplastic pulmonic valve is the characteristic cardiac anomaly
Hypertrophic cardiomyopathy (obstructive and non-obstructive) – seen in as many as 30%
Virtually all types of congenital heart defects have been described in patients with Noonan syndrome
Abdominal features
Hepatosplenomegaly unrelated to cardiac disease – seen in 25% of the patients
Genitourinary features
Renal anomalies are present in 10% of patients but are not clinically significant
More than half of male patients have undescended testes','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c0ea08669ee4","duplicate_sources":[{"record_id":"ab22302b44d194447f2a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1277,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"ab22302b44d194447f2a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1277,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 2-year-old boy is brought to your clinic due to a 3-day history of fever with occasional cough and coryza. On clinical\nhistory, viral upper respiratory tract infection is suspected. On physical examination, the patient is noted to have\ndown-slanting of palpebral fissures, eyes that are apart more than usual and low-set ears. The height of the patient is\nsmaller than the standard. Which one of the following is not consistent with this condition?","options":{"A":"Pulmonary valve stenosis.","B":"Myopia and ectopic ocular lens.","C":"An autosomal disorder involving mutation in chromosome 11.","D":"Webbed neck.","E":"Abnormalities in cardiac conduction and rhythm."},"source_answer":"B","source_explanation":"This clinical picture is suggestive of Noonan syndrome. This is an autosomal dominant disorder with mutation of\nchromosome 11. It has been described as the male Turner''s syndrome, but affects both sexes.\nClinical features of the syndrome include the following:\nFacial/eye features\nTriangular face\nHypertelorism (increased distance between the eyes)\nDown-slanting eyes\nPtosis\nStrabismus – seen in 48%\nAmblyopia – seen in 33%\nRefractive errors – seen in 61%\nLow-set ears with thickened helices\nHigh nasal bridge\nShort webbed neck\nChest/back features\nPectus carinatum/excavatum\nScoliosis\nCardiac features\nStenotic/dysplastic pulmonic valve is the characteristic cardiac anomaly\nHypertrophic cardiomyopathy (obstructive and non-obstructive) – seen in as many as 30%\nVirtually all types of congenital heart defects have been described in patients with Noonan syndrome\nAbdominal features\nHepatosplenomegaly unrelated to cardiac disease – seen in 25% of the patients\nGenitourinary features\nRenal anomalies are present in 10% of patients but are not clinically significant\nMore than half of male patients have undescended testes","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c0ea08669ee49916279e06f6f61a85b74ecc7ae3","duplicate_group_id":"exact-c0ea08669ee4","duplicate_sources":[{"record_id":"ab22302b44d194447f2a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1277,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_ev