INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6d89029bd3cf797096b0','Amedex 2023.pdf','1334','Mixed/Unclassified','A 9-year-old boy is brought to your attention by his parents because of poor exercise tolerance. He is a member of
the school basketball team but recently, it has been hard for him to play because he becomes short of breath and
tired soon after he starts playing. On examination, his height is at 97 percentile and weight at 3 percentile. Which one
of the following is the most important step in management?','{"A":"Karyotyping.","B":"Bone scan.","C":"Cardiac ultrasound.","D":"Growth hormone test.","E":"CT scan."}','C','Marfan syndrome (MFS) should always be considered as a probable diagnosis in children with tall stature and low
weight,
MFS is an autosomal dominant connective tissue disorder with involvement of the cardiovascular, skeletal and
ocular systems, as well as the skin, lungs and dura. The prevalence is at least 1 in 5000. In 90-93% of cases, MFS is
caused by mutations in FBN1. In a minority, MFS is caused by mutations in a second gene called TGFBR2. MFS
caused by this mutation is termed MFS2. Based on current statistics, MFS2 accounts for up to 10% of cases with
MFS.
Cardinal manifestations include aortic aneurysm and dissection, ocular lens dislocation and long bone overgrowth.
Cardiac disease is the leading cause of morbidity and mortality in patients with MFS. When the syndrome is
suspected based on clinical grounds, an echocardiogram (cardiac ultrasound scan) should follow as the most
appropriate next step in management for evaluation of aortic root dilation (the most important) and mitral valve
prolapse – conditions frequently seen in patients with MFS. The former is more common and significant clinically.
Serial echocardiographic surveillance is indicated for all affected individuals. Frequency should be tailored to each
individual by their cardiologist. Based on current evidence, the use of beta blockers remains the first-line treatment
(except where contra-indicated e.g., in asthmatic patients) in aortic dilatation in MFS even in young children if a
diagnosis of MFS is clear, or if there is a known FBN1 mutation in a young child without clinical features of MFS but
with affected first degree relative(s) with a known mutation and aortic root dilatation. If beta blockers are ineffective
or contraindicated, verapamil or ACE inhibitors would be the appropriate second-line treatment options.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1029","duplicate_group_id":"exact-d5ca10f75519","duplicate_sources":[{"record_id":"6d89029bd3cf797096b0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1334,"source_qid":"1029"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"6d89029bd3cf797096b0","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1334,"source_qid":"1029","domain_hint":"Mixed/Unclassified","stem":"A 9-year-old boy is brought to your attention by his parents because of poor exercise tolerance. He is a member of\nthe school basketball team but recently, it has been hard for him to play because he becomes short of breath and\ntired soon after he starts playing. On examination, his height is at 97 percentile and weight at 3 percentile. Which one\nof the following is the most important step in management?","options":{"A":"Karyotyping.","B":"Bone scan.","C":"Cardiac ultrasound.","D":"Growth hormone test.","E":"CT scan."},"source_answer":"C","source_explanation":"Marfan syndrome (MFS) should always be considered as a probable diagnosis in children with tall stature and low\nweight,\nMFS is an autosomal dominant connective tissue disorder with involvement of the cardiovascular, skeletal and\nocular systems, as well as the skin, lungs and dura. The prevalence is at least 1 in 5000. In 90-93% of cases, MFS is\ncaused by mutations in FBN1. In a minority, MFS is caused by mutations in a second gene called TGFBR2. MFS\ncaused by this mutation is termed MFS2. Based on current statistics, MFS2 accounts for up to 10% of cases with\nMFS.\nCardinal manifestations include aortic aneurysm and dissection, ocular lens dislocation and long bone overgrowth.\nCardiac disease is the leading cause of morbidity and mortality in patients with MFS. When the syndrome is\nsuspected based on clinical grounds, an echocardiogram (cardiac ultrasound scan) should follow as the most\nappropriate next step in management for evaluation of aortic root dilation (the most important) and mitral valve\nprolapse – conditions frequently seen in patients with MFS. The former is more common and significant clinically.\nSerial echocardiographic surveillance is indicated for all affected individuals. Frequency should be tailored to each\nindividual by their cardiologist. Based on current evidence, the use of beta blockers remains the first-line treatment\n(except where contra-indicated e.g., in asthmatic patients) in aortic dilatation in MFS even in young children if a\ndiagnosis of MFS is clear, or if there is a known FBN1 mutation in a young child without clinical features of MFS but\nwith affected first degree relative(s) with a known mutation and aortic root dilatation. If beta blockers are ineffective\nor contraindicated, verapamil or ACE inhibitors would be the appropriate second-line treatment options.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","asthma","management","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d5ca10f75519083fcc379e8144a0ae98a1712939","duplicate_group_id":"exact-d5ca10f75519","duplicate_sources":[{"record_id":"6d89029bd3cf797096b0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1334,"source_qid":"1029"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
