INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('02bf1be5e0a7dd10687d','Amedex 2023.pdf','1356','Mixed/Unclassified','A five-year-old boy is brought for evaluation by his parents concerning unusual behavior. He loves Popeye cartoon
and always remembers when it is shown on TV. At that time he turns on the TV. He becomes distraught and irritated
if he misses the cartoon. He has a goldfish and spends several hours staring at it with curiosity and fascination. His
favorite toy is wooden building blocks that he uses to make towers, break them and build them again. He did not say
his first word until the age of 2.5 years and could not use a communicative phrase at the age of 3 years. He does not
play with his peers and is not interested in making friends. During the examination, he adamantly avoids eye contact.
Which one of the following is the most likely diagnosis?','{"A":"Asperger syndrome.","B":"Autism.","C":"Mental retardation.","D":"Delayed developmental milestones.","E":"Obsessive-compulsive disorder."}','B','The persistent ritualism and preoccupations with activities (watching the Popeye cartoon) and objects (the building
blocks and the goldfish), delayed speech language development, poor communication with friends and avoiding eye
contact make Autistic disorder the most likely diagnosis in this child.
Autistic disorder is pervasive developmental disorder (PDD) affecting at least 4 children in 10000 with a male to
female ration of 4:1.
Characteristic features of autistic disorder include the following:
1- Onset during infancy and early childhood
2- An impairment of social interactions shown by at least two of the following:
lack of awareness of the feelings of others
absent or abnormal comfort seeking in response to distress
lack of imitation
absent or abnormal social play
impaired ability to socialize, including avoiding eye contact
3- Impairment in communication as shown by at least one of the following:
lack of babbling, gesture, mime or spoken language
absent or abnormal non-verbal communication
abnormalities in the form or content of speech
poor ability to initiate or sustain conversation
abnormal speech production
4- Restricted or repetitive activities, interests and imaginative development, shown in at least one of the following:
stereotyped body movements
persistent and unusual preoccupations and rituals with objects or activities
severe distress over changes in routine or environment
an absence of imaginative and symbolic play','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-9d967347ad07","duplicate_sources":[{"record_id":"02bf1be5e0a7dd10687d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1356,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"02bf1be5e0a7dd10687d","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1356,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A five-year-old boy is brought for evaluation by his parents concerning unusual behavior. He loves Popeye cartoon\nand always remembers when it is shown on TV. At that time he turns on the TV. He becomes distraught and irritated\nif he misses the cartoon. He has a goldfish and spends several hours staring at it with curiosity and fascination. His\nfavorite toy is wooden building blocks that he uses to make towers, break them and build them again. He did not say\nhis first word until the age of 2.5 years and could not use a communicative phrase at the age of 3 years. He does not\nplay with his peers and is not interested in making friends. During the examination, he adamantly avoids eye contact.\nWhich one of the following is the most likely diagnosis?","options":{"A":"Asperger syndrome.","B":"Autism.","C":"Mental retardation.","D":"Delayed developmental milestones.","E":"Obsessive-compulsive disorder."},"source_answer":"B","source_explanation":"The persistent ritualism and preoccupations with activities (watching the Popeye cartoon) and objects (the building\nblocks and the goldfish), delayed speech language development, poor communication with friends and avoiding eye\ncontact make Autistic disorder the most likely diagnosis in this child.\nAutistic disorder is pervasive developmental disorder (PDD) affecting at least 4 children in 10000 with a male to\nfemale ration of 4:1.\nCharacteristic features of autistic disorder include the following:\n1- Onset during infancy and early childhood\n2- An impairment of social interactions shown by at least two of the following:\nlack of awareness of the feelings of others\nabsent or abnormal comfort seeking in response to distress\nlack of imitation\nabsent or abnormal social play\nimpaired ability to socialize, including avoiding eye contact\n3- Impairment in communication as shown by at least one of the following:\nlack of babbling, gesture, mime or spoken language\nabsent or abnormal non-verbal communication\nabnormalities in the form or content of speech\npoor ability to initiate or sustain conversation\nabnormal speech production\n4- Restricted or repetitive activities, interests and imaginative development, shown in at least one of the following:\nstereotyped body movements\npersistent and unusual preoccupations and rituals with objects or activities\nsevere distress over changes in routine or environment\nan absence of imaginative and symbolic play","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"9d967347ad07472130c89ef88ee6d2208d2a4367","duplicate_group_id":"exact-9d967347ad07","duplicate_sources":[{"record_id":"02bf1be5e0a7dd10687d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1