INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ec1a1290e82d42f1ef88','Amedex 2023.pdf','1359','Mixed/Unclassified','A 7-year-old boy weighs 30 kg and has a body mass index of 19.5 kg/m2. Which one of the following is correct
regarding his weight and BMI (use the following chart for calculation)?
click to enlarge','{"A":"He is underweight.","B":"He is overweight.","C":"He has normal weight.","D":"He is obese.","E":"BMI is not applicable in children."}','D','Since the body composition changes with normal growth and stage of puberty, BMI in children is not a fixed measure
like it is in adults. BMI interpretation in children 2-18 years of age must be plotted on the sex-specific BMI percentile
charts. A 17-year-old boy with a BMI of 20 kg/m2 is within the normal range while a 6-year-old boy with the same
BMI is obese.
To check the weight status of a child, his/her BMI should be calculated by dividing the weight by the square of the
height in meter. The BMI then should be plotted on the sex-specific BMI percentile to see in which zone it is. This
child’s BMI lies in the ‘obesity’ zone (see the chart below).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-3ad959c3f274","duplicate_sources":[{"record_id":"ec1a1290e82d42f1ef88","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1359,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"ec1a1290e82d42f1ef88","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1359,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 7-year-old boy weighs 30 kg and has a body mass index of 19.5 kg/m2. Which one of the following is correct\nregarding his weight and BMI (use the following chart for calculation)?\nclick to enlarge","options":{"A":"He is underweight.","B":"He is overweight.","C":"He has normal weight.","D":"He is obese.","E":"BMI is not applicable in children."},"source_answer":"D","source_explanation":"Since the body composition changes with normal growth and stage of puberty, BMI in children is not a fixed measure\nlike it is in adults. BMI interpretation in children 2-18 years of age must be plotted on the sex-specific BMI percentile\ncharts. A 17-year-old boy with a BMI of 20 kg/m2 is within the normal range while a 6-year-old boy with the same\nBMI is obese.\nTo check the weight status of a child, his/her BMI should be calculated by dividing the weight by the square of the\nheight in meter. The BMI then should be plotted on the sex-specific BMI percentile to see in which zone it is. This\nchild’s BMI lies in the ‘obesity’ zone (see the chart below).","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"3ad959c3f2748597b3a3135e4afdafc43851477a","duplicate_group_id":"exact-3ad959c3f274","duplicate_sources":[{"record_id":"ec1a1290e82d42f1ef88","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1359,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
