INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('ec1a1290e82d42f1ef88','src-v294-687f312c',NULL,'1359','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 7-year-old boy weighs 30 kg and has a body mass index of 19.5 kg/m2. Which one of the following is correct
regarding his weight and BMI (use the following chart for calculation)?
click to enlarge',NULL,'D','Since the body composition changes with normal growth and stage of puberty, BMI in children is not a fixed measure
like it is in adults. BMI interpretation in children 2-18 years of age must be plotted on the sex-specific BMI percentile
charts. A 17-year-old boy with a BMI of 20 kg/m2 is within the normal range while a 6-year-old boy with the same
BMI is obese.
To check the weight status of a child, his/her BMI should be calculated by dividing the weight by the square of the
height in meter. The BMI then should be plotted on the sex-specific BMI percentile to see in which zone it is. This
child’s BMI lies in the ‘obesity’ zone (see the chart below).',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-3ad959c3f274","duplicate_sources":[{"record_id":"ec1a1290e82d42f1ef88","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1359,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
