INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('74788e6ff866abb22ca9','Amedex 2023.pdf','1363','Mixed/Unclassified','A 5-year-old child is brought to your practice by his parents with complaints of fever and ear pain. On examination, he
is in mild distress and has a fever of 38.3°C. Otoscopic examination reveals a red bulging tympanic membrane on
the right side with decreased mobility. Which one of the following is more likely to have caused this presentation?','{"A":"Hemophilus influenza.","B":"Streptococcus pneumoniae.","C":"Pseudomonas aeruginosa.","D":"RSV virus.","E":"Moraxella catarrhalis."}','B','A red bulging tympanic membrane with decreased mobility is the classic finding in acute otitis media (AOM).
In children older than 6 weeks, AOM is caused by bacteria in majority of cases. Streptococcus pneumoniae,
Hemophilus influenzae, Moraxella catarrhalis, and Streptococcus pyogenes are responsible for the majority of
episodes of AOM in persons older than 6 weeks. Other bacteria implicated in AOM include Staphylococcus aureus,
streptococcus viridans, and Pseudomonas aeruginosa.
Of these, Streptococcus pneumoniae is the most common etiologic agent responsible for AOM and for invasive
bacterial infections in children of all age groups, followed by Hemophilus influenzae as the second most common
etiologic factor.
RSV virus is the etiologic factor, mostly in neonates. Infection with this virus is associated with pneumonia,
bronchiolitis and otitis media in this age group; however, streptococcus pneumoniae remains the most common
etiologic factor for AOM even in this age group.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1343","duplicate_group_id":"exact-43071f4decea","duplicate_sources":[{"record_id":"74788e6ff866abb22ca9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1363,"source_qid":"1343"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"74788e6ff866abb22ca9","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1363,"source_qid":"1343","domain_hint":"Mixed/Unclassified","stem":"A 5-year-old child is brought to your practice by his parents with complaints of fever and ear pain. On examination, he\nis in mild distress and has a fever of 38.3°C. Otoscopic examination reveals a red bulging tympanic membrane on\nthe right side with decreased mobility. Which one of the following is more likely to have caused this presentation?","options":{"A":"Hemophilus influenza.","B":"Streptococcus pneumoniae.","C":"Pseudomonas aeruginosa.","D":"RSV virus.","E":"Moraxella catarrhalis."},"source_answer":"B","source_explanation":"A red bulging tympanic membrane with decreased mobility is the classic finding in acute otitis media (AOM).\nIn children older than 6 weeks, AOM is caused by bacteria in majority of cases. Streptococcus pneumoniae,\nHemophilus influenzae, Moraxella catarrhalis, and Streptococcus pyogenes are responsible for the majority of\nepisodes of AOM in persons older than 6 weeks. Other bacteria implicated in AOM include Staphylococcus aureus,\nstreptococcus viridans, and Pseudomonas aeruginosa.\nOf these, Streptococcus pneumoniae is the most common etiologic agent responsible for AOM and for invasive\nbacterial infections in children of all age groups, followed by Hemophilus influenzae as the second most common\netiologic factor.\nRSV virus is the etiologic factor, mostly in neonates. Infection with this virus is associated with pneumonia,\nbronchiolitis and otitis media in this age group; however, streptococcus pneumoniae remains the most common\netiologic factor for AOM even in this age group.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"43071f4deceab18bad6b8add4dd596e1e1fe16cf","duplicate_group_id":"exact-43071f4decea","duplicate_sources":[{"record_id":"74788e6ff866abb22ca9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1363,"source_qid":"1343"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
