INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e207f7fd03329b7ebd87','Amedex 2023.pdf','1371','Mixed/Unclassified','A 6-yer-old girl is brought to your general practice by her mother, who is concerned about a neck mass in her
daughter. The mass is shown in the following photograph. The child is otherwise healthy. On examination, there is a
non-tender neck mass in the midline moving with swallowing and tongue protrusion. The rest of the physical
examination is unremarkable. Which one of the following could be the most likely complication of this neck mass?','{"A":"Infection.","B":"Malignancy.","C":"Fistula formation.","D":"Overgrowth and compression of underlying structures.","E":"Rupture."}','A','The clinical presentation and the photograph are highly suggestive of thyroglossal duct cyst (TDC) as the most likely
diagnosis. TDC is the most common type of developmental cyst encountered in the neck region. TDC occurs when
the thyroglossal duct fails to obliterate and forms a bridge between the base of the tongue and the thyroid gland.
A TDC usually presents with an asymptomatic palpable midline neck mass usually at or below the level of the hyoid
bone, above the thyroid cartilage. The mass is most often in the midline, although it can present slightly off the
midline to one side or the other. A TDC may present in childhood (less than 50%) or later in life, usually as a young
adult below the age of 20 years.
Characteristically on examination, a TDC moves up when the tongue is protruded, and moves up and down upon
swallowing reflecting the attachment of these cysts to the base of the tongue by the thyroglossal tract. Some
patients have neck or throat pain, or dysphagia, but most patients are just concerned by the lump itself.
A TDC may become complicated. Complications of TDCs include:
Infection.
Malignancy.
Overgrowth and pressure of the underlying structures.
Rupture and fistula formation.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-508db62b9b8b","duplicate_sources":[{"record_id":"e207f7fd03329b7ebd87","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1371,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"e207f7fd03329b7ebd87","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1371,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 6-yer-old girl is brought to your general practice by her mother, who is concerned about a neck mass in her\ndaughter. The mass is shown in the following photograph. The child is otherwise healthy. On examination, there is a\nnon-tender neck mass in the midline moving with swallowing and tongue protrusion. The rest of the physical\nexamination is unremarkable. Which one of the following could be the most likely complication of this neck mass?","options":{"A":"Infection.","B":"Malignancy.","C":"Fistula formation.","D":"Overgrowth and compression of underlying structures.","E":"Rupture."},"source_answer":"A","source_explanation":"The clinical presentation and the photograph are highly suggestive of thyroglossal duct cyst (TDC) as the most likely\ndiagnosis. TDC is the most common type of developmental cyst encountered in the neck region. TDC occurs when\nthe thyroglossal duct fails to obliterate and forms a bridge between the base of the tongue and the thyroid gland.\nA TDC usually presents with an asymptomatic palpable midline neck mass usually at or below the level of the hyoid\nbone, above the thyroid cartilage. The mass is most often in the midline, although it can present slightly off the\nmidline to one side or the other. A TDC may present in childhood (less than 50%) or later in life, usually as a young\nadult below the age of 20 years.\nCharacteristically on examination, a TDC moves up when the tongue is protruded, and moves up and down upon\nswallowing reflecting the attachment of these cysts to the base of the tongue by the thyroglossal tract. Some\npatients have neck or throat pain, or dysphagia, but most patients are just concerned by the lump itself.\nA TDC may become complicated. Complications of TDCs include:\nInfection.\nMalignancy.\nOvergrowth and pressure of the underlying structures.\nRupture and fistula formation.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"508db62b9b8bb6bac5b396577827ebff681e6067","duplicate_group_id":"exact-508db62b9b8b","duplicate_sources":[{"record_id":"e207f7fd03329b7ebd87","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1371,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=e