INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('100945b4734920be8abd','Amedex 2023.pdf','1459','Mixed/Unclassified','An 82-year-old man male presents to the emergency department with a knife in his hand. He claims
that he hears voices saying his neighbors want to kill him and he should kill them before they kill
him. You, as the attending physician, manage to verbally de-escalate him and convince him to
surrender his knife. Which one of the following would be the next best step in management?','{"A":"Call the hospital security.","B":"Call the police.","C":"Call his family to help you with dealing with him.","D":"Calm him down and talk to him.","E":"Offer him tea and biscuit."}','A','The presentation is typical of acute psychosis and command hallucinations. Any patient with
command hallucinations to harm self or others is at significant risk of developing violence sooner
or later.
Although apparently this patient is ready to surrender his knife now, with command hallucinations
he may still pose risk to himself or others.
Under circumstances such as this one, calling the hospital security would be the next best step in
management. This will ensure the safety of you and the staff while you are planning further
measures.
(Option B) Calling the police was an appropriate option if this situation happened in the community
and not in a medical facility.
(Option C) Calling his family will provide an opportunity to obtain more information about his
medical and psychiatric history; however, security and safety comes first.
(Options D and E) Verbal de-escalation to calm the patient or measures to establish rapport such
as offering tea and biscuits is appropriate after saefty is ensured by the hospital security.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"63","duplicate_group_id":"exact-ef6164c81703","duplicate_sources":[{"record_id":"100945b4734920be8abd","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1459,"source_qid":"63"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"100945b4734920be8abd","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1459,"source_qid":"63","domain_hint":"Mixed/Unclassified","stem":"An 82-year-old man male presents to the emergency department with a knife in his hand. He claims\nthat he hears voices saying his neighbors want to kill him and he should kill them before they kill\nhim. You, as the attending physician, manage to verbally de-escalate him and convince him to\nsurrender his knife. Which one of the following would be the next best step in management?","options":{"A":"Call the hospital security.","B":"Call the police.","C":"Call his family to help you with dealing with him.","D":"Calm him down and talk to him.","E":"Offer him tea and biscuit."},"source_answer":"A","source_explanation":"The presentation is typical of acute psychosis and command hallucinations. Any patient with\ncommand hallucinations to harm self or others is at significant risk of developing violence sooner\nor later.\nAlthough apparently this patient is ready to surrender his knife now, with command hallucinations\nhe may still pose risk to himself or others.\nUnder circumstances such as this one, calling the hospital security would be the next best step in\nmanagement. This will ensure the safety of you and the staff while you are planning further\nmeasures.\n(Option B) Calling the police was an appropriate option if this situation happened in the community\nand not in a medical facility.\n(Option C) Calling his family will provide an opportunity to obtain more information about his\nmedical and psychiatric history; however, security and safety comes first.\n(Options D and E) Verbal de-escalation to calm the patient or measures to establish rapport such\nas offering tea and biscuits is appropriate after saefty is ensured by the hospital security.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ef6164c81703bf150b79e81c36dd4244b72d686e","duplicate_group_id":"exact-ef6164c81703","duplicate_sources":[{"record_id":"100945b4734920be8abd","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1459,"source_qid":"63"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,activ