INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('1f66c5a2e735cf72db35','Amedex 2023.pdf','1467','Mixed/Unclassified','Ali, 45 years old is in your office with his wife who is concerned about him and insisted that he sees
a doctor because he seems to have been ‘lost’ and ‘confused’ since he had a severe car accident
and lost one of his best friends who was in the car with him 5 months ago. He only sustained a
head injury in the accident which was cleared as a minor one with no serious complications at that
time. Which of the following could be the most likely cause to this presentation?','{"A":"Major depressive disorder.","B":"Post-traumatic stress disorder.","C":"Post-concussion syndrome.","D":"Late-onset schizophrenia.","E":"Dementia."}','C','This Scenario represents a common undiagnosed and mistreated condition seen in general
practice after a head trauma, namely post-concussion syndrome (PCS).
Concussion is a temporary disturbance in brain function following a trauma to the head. It can also
occur after a blow to the body. Concussion can present with a variety of signs and symptoms
including:
Cognitive related symptoms:
Difficulty concentrating
Difficulty finding things
Difficulty reading
Memory problems
Brain fog
Easily distracted
Mood-related symptoms:
Anxiety
Depression
Feeling overwhelmed
Irritability
Low-energy or motivation
Various other mood/personality changes
Sensory-related symptoms:
Blurred vision
Car sickness or nausea with motion
Change in (or loss of) taste or smell
Ringing ears','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-6fa2d6c04bce","duplicate_sources":[{"record_id":"1f66c5a2e735cf72db35","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1467,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"1f66c5a2e735cf72db35","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1467,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Ali, 45 years old is in your office with his wife who is concerned about him and insisted that he sees\na doctor because he seems to have been ‘lost’ and ‘confused’ since he had a severe car accident\nand lost one of his best friends who was in the car with him 5 months ago. He only sustained a\nhead injury in the accident which was cleared as a minor one with no serious complications at that\ntime. Which of the following could be the most likely cause to this presentation?","options":{"A":"Major depressive disorder.","B":"Post-traumatic stress disorder.","C":"Post-concussion syndrome.","D":"Late-onset schizophrenia.","E":"Dementia."},"source_answer":"C","source_explanation":"This Scenario represents a common undiagnosed and mistreated condition seen in general\npractice after a head trauma, namely post-concussion syndrome (PCS).\nConcussion is a temporary disturbance in brain function following a trauma to the head. It can also\noccur after a blow to the body. Concussion can present with a variety of signs and symptoms\nincluding:\nCognitive related symptoms:\nDifficulty concentrating\nDifficulty finding things\nDifficu